def top_words(text: str, k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []

    word_counts = {}

    cleaned_chars = [c.lower() for c in text]

    i = 0
    while i < len(cleaned_chars):
        char = cleaned_chars[i]
        if 'a' <= char <= 'z':
            start = i
            while i < len(cleaned_chars) and 'a' <= cleaned_chars[i] <= 'z':
                i += 1
            word = ''.join(cleaned_chars[start:i])
            if word in word_counts:
                word_counts[word] += 1
            else:
                word_counts[word] = 1
        else:
            i += 1

    sorted_words = sorted(word_counts.items(), key=lambda x: (-x[1], x[0]))

    return sorted_words[:k]
