class InsufficientFunds(Exception):
    """Exception raised when withdrawal exceeds available balance."""
    pass

class BankAccount:
    def __init__(self, owner: str, balance: float = 0):
        if balance < 0:
            raise ValueError("Starting balance cannot be negative.")

        self.owner = owner
        self._balance = balance
        self.history = []

    def deposit(self, amount: float) -> None:
        """Add an amount to the account."""
        if amount <= 0:
            raise ValueError("Deposit amount must be positive.")

        self._balance += amount
        self.history.append(("deposit", amount))

    def withdraw(self, amount: float) -> None:
        """Remove an amount from the account. Raises InsufficientFunds if insufficient funds."""
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive.")

        if amount > self._balance:
            raise InsufficientFunds(f"Insufficient funds to withdraw {amount}.")

        self._balance -= amount
        self.history.append(("withdraw", amount))

    @property
    def balance(self) -> float:
        """Return the current balance (read-only)."""
        return self._balance
