from typing import Any, Dict, List, Type

def validate(data: dict, schema: dict[str, type]) -> list[str]:
    """
    Validate a dictionary against a schema mapping field names to types.

    Args:
        data: The dictionary to validate.
        schema: A dictionary mapping field names to their expected Python types.

    Returns:
        A sorted list of error strings indicating validation failures.
        Error formats:
            - "missing: <field>" for required fields not present in data.
            - "type: <field>" when the value is not an instance of the expected type.
              Note: bool does not count as int, and int does not count as float.
            - "extra: <field>" for keys in data not present in schema.

    Raises:
        TypeError: If schema contains non-type values or data is not a dictionary.
    """
    errors = []

    # Validate schema structure
    if not isinstance(schema, dict):
        raise TypeError("Schema must be a dictionary.")

    for field, expected_type in schema.items():
        if not isinstance(expected_type, type):
            raise TypeError(f"Expected value for '{field}' must be a Python type, got {type(expected_type).__name__}.")

    # Validate data structure
    if not isinstance(data, dict):
        raise TypeError("Data must be a dictionary.")

    # Check for missing fields and type mismatches
    for field, expected_type in schema.items():
        if field not in data:
            errors.append(f"missing: {field}")
        else:
            value = data[field]

            # Special handling for bool vs int comparison
            if expected_type == bool:
                if not isinstance(value, bool):
                    errors.append(f"type: {field}")
            elif expected_type == int and isinstance(value, bool):
                errors.append(f"type: {field}")
            elif expected_type == float and isinstance(value, int) and not isinstance(value, float):
                errors.append(f"type: {field}")
            elif not isinstance(value, expected_type):
                # Ensure we don't treat int as float or vice versa incorrectly
                if expected_type in (int, float):
                    if isinstance(value, type(expected_type)) and type(value).__name__ != expected_type.__name__:
                        errors.append(f"type: {field}")
                    elif not isinstance(value, expected_type):
                        errors.append(f"type: {field}")
                else:
                    if not isinstance(value, expected_type):
                        errors.append(f"type: {field}")

    # Check for extra fields
    extra_fields = set(data.keys()) - set(schema.keys())
    for field in sorted(extra_fields):
        errors.append(f"extra: {field}")

    return sorted(errors)
