from typing import Any, Dict, List, Type

def validate(data: dict, schema: dict[str, type]) -> list[str]:
    """
    Validate a dictionary against a schema of required fields and their types.

    Args:
        data: The dictionary to validate.
        schema: A dictionary mapping field names to their expected Python types.

    Returns:
        A sorted list of error strings for validation failures.
    """
    errors = []

    # Check for missing required fields and type mismatches
    for field, expected_type in schema.items():
        if field not in data:
            errors.append(f"missing: {field}")
        else:
            value = data[field]
            try:
                # bool is a subclass of int, so we need to check explicitly
                # to ensure bool does not count as int.
                is_bool = isinstance(value, bool)
                is_int = isinstance(value, int) and not is_bool

                if expected_type == int:
                    if not is_int:
                        errors.append(f"type: {field}")
                elif expected_type == float:
                    # Check for subclass of float to avoid catching complex numbers etc.
                    if not isinstance(value, float):
                        errors.append(f"type: {field}")
                else:
                    # For other types, use standard isinstance check.
                    if not isinstance(value, expected_type):
                        errors.append(f"type: {field}")
            except Exception:
                # If any unexpected error occurs during type checking, we report it as a type error.
                errors.append(f"type: {field}")

    # Check for extra keys in data that are not in schema
    extra_fields = set(data.keys()) - set(schema.keys())
    if extra_fields:
        sorted_extra = sorted(extra_fields)
        for field in sorted_extra:
            errors.append(f"extra: {field}")

    return sorted(errors)
